local UmbrellaMaker = {}
local PRODUCTS = {
    simple_oilcloth_umbrella = { name = "Preprosto oljnopláštno dežnik", woodCost = 2, linenCost = 2, time = 4, cost = 60, beauty = 18, happiness = 1, description = "Preprosto oljnopláštno dežnik za deževne dni." },
    silk_parasol = { name = "Svileni sončnik", woodCost = 2, silkCost = 2, linenCost = 1, time = 7, cost = 180, beauty = 35, happiness = 2, prestige = 3, description = "Svileni sončnik za trgovce." },
    silver_handle_umbrella = { name = "Srebrnorokavni dežnik", woodCost = 2, silkCost = 2, silverCost = 1, linenCost = 1, time = 10, cost = 440, beauty = 50, happiness = 2, prestige = 8, description = "Srebrnorokavni dežnik za plemiče." },
    gold_trimmed_parasol = { name = "Zlatookrasni sončnik", woodCost = 2, silkCost = 2, goldCost = 1, silverCost = 1, linenCost = 1, time = 14, cost = 1000, beauty = 65, happiness = 3, prestige = 16, description = "Zlatookrasni sončnik za visoke plemiče." },
    jewel_pommel_umbrella = { name = "Draguljnogrbi dežnik", woodCost = 2, silkCost = 2, goldCost = 1, silverCost = 1, linenCost = 1, jewelCost = 1, time = 18, cost = 2200, beauty = 80, happiness = 5, prestige = 30, description = "Dežnik z draguljnim grbičem za visoko plemstvo." },
    royal_grand_umbrella = { name = "Kraljevski veliki dežnik", woodCost = 3, silkCost = 3, goldCost = 2, silverCost = 2, linenCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 5000, beauty = 95, happiness = 12, prestige = 60, description = "Veliki kraljevski dežnik z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    umbrella_workshop = { name = "Dežnična delavnica", cost = { gold = 240, wood = 120, stone = 100, linen = 6 }, upkeep = 5, qualityBonus = 5 },
    parasol_loft = { name = "Sončniška podstrešje", cost = { gold = 880, wood = 240, stone = 220, silk = 6, silver = 6 }, upkeep = 20, qualityBonus = 18 },
    master_umbrella_atelier = { name = "Mojstrski dežnični atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_umbrella_palace = { name = "Kraljevska dežnična palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
UmbrellaMaker.woodStock = 14; UmbrellaMaker.linenStock = 12; UmbrellaMaker.silkStock = 12; UmbrellaMaker.silverStock = 6; UmbrellaMaker.goldStock = 6; UmbrellaMaker.jewelStock = 4; UmbrellaMaker.pearlStock = 4
UmbrellaMaker.productStock = {}; UmbrellaMaker.buildings = {}; UmbrellaMaker.maker = nil; UmbrellaMaker.activeMaking = {}; UmbrellaMaker.totalProducts = 0; UmbrellaMaker.dayTimer = 0
function UmbrellaMaker.init() UmbrellaMaker.woodStock=14; UmbrellaMaker.linenStock=12; UmbrellaMaker.silkStock=12; UmbrellaMaker.silverStock=6; UmbrellaMaker.goldStock=6; UmbrellaMaker.jewelStock=4; UmbrellaMaker.pearlStock=4; UmbrellaMaker.productStock={}; UmbrellaMaker.buildings={}; UmbrellaMaker.maker=nil; UmbrellaMaker.activeMaking={}; UmbrellaMaker.totalProducts=0; UmbrellaMaker.dayTimer=0; print("[UmbrellaMaker] Royal Umbrella Maker System initialized (6 products, 4 buildings)") end
function UmbrellaMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; UmbrellaMaker.maker={name=n or ("Dežničar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dežničar najet: %s (spretnost: %d)",UmbrellaMaker.maker.name,s),"success") end; return true end
function UmbrellaMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function UmbrellaMaker.build(id) local ok,e=UmbrellaMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(UmbrellaMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function UmbrellaMaker.getQualityBonus() local b=0; for _,bd in ipairs(UmbrellaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function UmbrellaMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and UmbrellaMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.linenCost and UmbrellaMaker.linenStock<(d.linenCost or 0) then return false,"Premalo lanu" end; if d.silkCost and UmbrellaMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.silverCost and UmbrellaMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and UmbrellaMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and UmbrellaMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and UmbrellaMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #UmbrellaMaker.buildings==0 then return false,"Potrebna dežnična delavnica" end; if not UmbrellaMaker.maker then return false,"Potreben dežničar" end; return true end
function UmbrellaMaker.make(pt,qty) qty=qty or 1; local ok,e=UmbrellaMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then UmbrellaMaker.woodStock=UmbrellaMaker.woodStock-d.woodCost*qty end; if d.linenCost then UmbrellaMaker.linenStock=UmbrellaMaker.linenStock-d.linenCost*qty end; if d.silkCost then UmbrellaMaker.silkStock=UmbrellaMaker.silkStock-d.silkCost*qty end; if d.silverCost then UmbrellaMaker.silverStock=UmbrellaMaker.silverStock-d.silverCost*qty end; if d.goldCost then UmbrellaMaker.goldStock=UmbrellaMaker.goldStock-d.goldCost*qty end; if d.jewelCost then UmbrellaMaker.jewelStock=UmbrellaMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then UmbrellaMaker.pearlStock=UmbrellaMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if UmbrellaMaker.maker then t=math.max(1,t-math.floor(UmbrellaMaker.maker.skill/13)) end; table.insert(UmbrellaMaker.activeMaking,{id="umbrella_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function UmbrellaMaker.completeMaking(m) local q=1.0+(UmbrellaMaker.getQualityBonus()/100); if UmbrellaMaker.maker then q=q+(UmbrellaMaker.maker.skill/140) end; q=math.min(2.5,q); UmbrellaMaker.productStock[m.productType]=(UmbrellaMaker.productStock[m.productType] or 0)+m.quantity; UmbrellaMaker.totalProducts=UmbrellaMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if UmbrellaMaker.maker then UmbrellaMaker.maker.itemsMade=UmbrellaMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then UmbrellaMaker.maker.skill=math.min(100,UmbrellaMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dežnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"umbrella.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function UmbrellaMaker.update(dt) if not _G.state then return end; UmbrellaMaker.dayTimer=UmbrellaMaker.dayTimer+dt; if UmbrellaMaker.dayTimer>=30 then UmbrellaMaker.dayTimer=0; for i=#UmbrellaMaker.activeMaking,1,-1 do local m=UmbrellaMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then UmbrellaMaker.completeMaking(m); table.remove(UmbrellaMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(UmbrellaMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if UmbrellaMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function UmbrellaMaker.getStats() return {woodStock=UmbrellaMaker.woodStock,linenStock=UmbrellaMaker.linenStock,silkStock=UmbrellaMaker.silkStock,silverStock=UmbrellaMaker.silverStock,goldStock=UmbrellaMaker.goldStock,jewelStock=UmbrellaMaker.jewelStock,pearlStock=UmbrellaMaker.pearlStock,productStock=UmbrellaMaker.productStock,numBuildings=#UmbrellaMaker.buildings,hasMaker=UmbrellaMaker.maker~=nil,makerName=UmbrellaMaker.maker and UmbrellaMaker.maker.name or "—",makerSkill=UmbrellaMaker.maker and UmbrellaMaker.maker.skill or 0,activeMaking=#UmbrellaMaker.activeMaking,totalProducts=UmbrellaMaker.totalProducts} end
return UmbrellaMaker
